query:
SELECT DISTINCT ?item ?matchedLabel ?en ?zh ?description ?kind WHERE {
          VALUES ?matchedLabel { "Chinese remainder theorem"@en "Diophantine equation"@en "Euclidean algorithm"@en "Euler's totient function"@en "Fermat's little theorem"@en "abelian group"@en "algebraic number"@en "alternating group"@en "associativity"@en "automorphism"@en "base case"@en "chinese remainder theorem"@en "commutativity"@en "completeness"@en "complex number"@en "composite number"@en "congruence"@en "conjunction"@en "consistency"@en "continued fraction"@en "coprime"@en "coset"@en "cyclic group"@en "decidability"@en "diophantine equation"@en "disjunction"@en "distributivity"@en "divisibility"@en "divisor"@en "endomorphism"@en "euclidean algorithm"@en "euler's totient function"@en "existential quantifier"@en "fermat's little theorem"@en "first-order logic"@en "formal proof"@en "formal system"@en "formalization"@en "fundamental theorem of arithmetic"@en "greatest common divisor"@en "group"@en "group action"@en "group homomorphism"@en "higher-order logic"@en "homomorphism"@en "identity element"@en "imaginary unit"@en "induction hypothesis"@en "inductive step"@en "integer"@en "inverse element"@en "irrational number"@en "isomorphism"@en "kernel"@en "least common multiple"@en "mathematical induction"@en "modular arithmetic"@en "monoid"@en "multiple"@en "natural number"@en "negation"@en "normal subgroup"@en "orbit"@en "permutation group"@en "predicate"@en "predicate logic"@en "prime factorization"@en "prime number"@en "propositional logic"@en "quadratic residue"@en "quotient group"@en "rational number"@en "real number"@en "residue class"@en "semigroup"@en "soundness"@en "stabilizer"@en "strong induction"@en "structural induction"@en "subgroup"@en "symmetric group"@en "tautology"@en "transcendental number"@en "undecidable"@en "universal quantifier"@en }
          ?item (rdfs:label|skos:altLabel) ?matchedLabel.
          OPTIONAL { ?item rdfs:label ?en. FILTER(LANG(?en)="en") }
          OPTIONAL { ?item rdfs:label ?zh. FILTER(LANG(?zh) IN ("zh-hans","zh-cn","zh")) }
          OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
          OPTIONAL { ?item wdt:P31 ?kind }
        }
